// Una web por ejecución (modo "Run Once for Each Item"). Se mide el
// tiempo de respuesta a mano porque el nodo HTTP Request no lo expone, y
// se captura cualquier fallo de red como "caída" en vez de romper el flujo
// (equivalente a Continue On Fail, pero con control total del resultado).
const site = $input.item.json;
const start = Date.now();

let ok = false;
let statusCode = null;
let responseMs = null;
let error = null;

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: site.url,
    timeout: 10000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  responseMs = Date.now() - start;
  statusCode = response.statusCode;
  ok = statusCode >= 200 && statusCode < 400;
  if (!ok) {
    error = `HTTP ${statusCode}`;
  }
} catch (err) {
  responseMs = Date.now() - start;
  error = (err && err.message) ? err.message.slice(0, 500) : 'Error de red';
}

return {
  json: {
    site_id: site.id,
    site_name: site.name,
    site_url: site.url,
    ok,
    status_code: statusCode,
    response_ms: responseMs,
    error,
  },
};

// Abre o cierra la incidencia de "caída" para este site, comparando el
// estado actual (últimas 3 comprobaciones) con si ya hay una incidencia
// abierta. Misma regla de 3 fallos consecutivos que lib/metrics/status.ts.
const DOWN_AFTER_CONSECUTIVE_FAILURES = 3;

const check = $('Comprobar disponibilidad').item.json;
const baseUrl = $env.SUPABASE_URL;
const headers = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
};

const recentChecks = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/rest/v1/checks`,
  qs: {
    site_id: `eq.${check.site_id}`,
    select: 'ok',
    order: 'checked_at.desc',
    limit: String(DOWN_AFTER_CONSECUTIVE_FAILURES),
  },
  headers,
  json: true,
});

const isDown =
  recentChecks.length === DOWN_AFTER_CONSECUTIVE_FAILURES &&
  recentChecks.every((c) => c.ok === false);

const openIncidents = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/rest/v1/incidents`,
  qs: {
    site_id: `eq.${check.site_id}`,
    kind: 'eq.down',
    resolved_at: 'is.null',
    select: 'id,opened_at',
    order: 'opened_at.desc',
    limit: '1',
  },
  headers,
  json: true,
});
const openIncident = openIncidents[0] ?? null;

let action = 'none';
let message = null;

if (isDown && !openIncident) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}/rest/v1/incidents`,
    headers: { ...headers, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
    body: {
      site_id: check.site_id,
      kind: 'down',
      severity: 'critical',
      detail: check.error,
    },
    json: true,
  });
  action = 'opened';
  message = `🔴 ${check.site_name} no responde (${check.error ?? `HTTP ${check.status_code}`}).\n${check.site_url}`;
} else if (!isDown && openIncident) {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${baseUrl}/rest/v1/incidents`,
    qs: { id: `eq.${openIncident.id}` },
    headers: { ...headers, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
    body: { resolved_at: new Date().toISOString() },
    json: true,
  });
  const openedMinutes = Math.round((Date.now() - new Date(openIncident.opened_at).getTime()) / 60000);
  action = 'closed';
  message = `🟢 ${check.site_name} ha vuelto (caída de ${openedMinutes} min).\n${check.site_url}`;
}

return { json: { action, message } };
